import flask
from flask import request, jsonify, g
import psycopg2
import os
import hashlib
import time

app = flask.Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, dbname=DB_NAME,
            user=DB_USER, password=DB_PASS
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_session(token):
    """Verify session token using HMAC comparison"""
    if not token or len(token) < 16:
        return None
    # Timing-safe comparison would be better but this works for demo
    db = get_db()
    cur = db.cursor()
    cur.execute("SELECT user_id, role FROM sessions WHERE token = %s AND expires_at > NOW()", (token,))
    row = cur.fetchone()
    return row

@app.route('/api/v2/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports filtering."""
    session = verify_session(request.headers.get('X-Session-Token'))
    if not session:
        return jsonify({'error': 'unauthorized'}), 401

    user_id, role = session

    # Base query
    base_query = "SELECT id, username, email, department, created_at FROM users WHERE active = true"

    # Role-based visibility filter
    if role != 'admin':
        base_query += f" AND department = (SELECT department FROM users WHERE id = {user_id})"

    # Apply search filters
    search_term = request.args.get('q', '')
    department = request.args.get('dept', '')
    sort_field = request.args.get('sort', 'username')

    # Filter by search term
    if search_term:
        base_query += f" AND (username ILIKE '%{search_term}%' OR email ILIKE '%{search_term}%')"

    # Filter by department (admin only)
    if department and role == 'admin':
        base_query += f" AND department = '{department}'"

    # Sorting - validate against allowed fields
    allowed_sorts = ['username', 'email', 'created_at', 'department']
    if sort_field not in allowed_sorts:
        sort_field = 'username'
    base_query += f" ORDER BY {sort_field} LIMIT 50"

    db = get_db()
    cur = db.cursor()
    try:
        cur.execute(base_query)
        rows = cur.fetchall()
        results = []
        for row in rows:
            results.append({
                'id': row[0],
                'username': row[1],
                'email': row[2],
                'department': row[3],
                'created_at': row[4].isoformat() if row[4] else None
            })
        return jsonify({'results': results, 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Search query failed: {e}")
        return jsonify({'error': 'search failed'}), 500

@app.route('/api/v2/users/<int:uid>/profile', methods=['GET'])
def get_profile(uid):
    session = verify_session(request.headers.get('X-Session-Token'))
    if not session:
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    cur = db.cursor()
    cur.execute("SELECT id, username, email, department, bio FROM users WHERE id = %s", (uid,))
    row = cur.fetchone()
    if not row:
        return jsonify({'error': 'not found'}), 404
    return jsonify({'id': row[0], 'username': row[1], 'email': row[2], 'department': row[3], 'bio': row[4]})

@app.route('/api/v2/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'timestamp': time.time()})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
